// ============================================================================
// n8n Code node: "Build Review Context"   (Mode: Run Once for All Items)
//
// Parses the Bitbucket Data Center PR diff JSON and splits it into CHUNKS.
// Output = one item per chunk; each AI agent runs once per item.
//
// Each item carries:
//   - files[]       : canonical files of this chunk with GLOBAL ids (F1..Fn)
//                     -> the ONLY source of truth for file paths
//   - lineIndex     : { path: { "<newLine>": {lineType, text} } } for this chunk
//                     -> every line Bitbucket will accept an inline comment on
//   - annotatedDiff : this chunk's changed files IN FULL (from "Get Changed File"),
//                     every line numbered, + = added, - = removed (inline at its
//                     position). Falls back to the plain diff hunks when the file
//                     could not be fetched or exceeds MAX_FILE_CHARS.
//   - repoRules     : GLOBAL_RULES + repo rules file (from the PR SOURCE branch)
//   - hasRules      : false when there are no rules -> the rules reviewer is skipped
// ============================================================================

const cfg = $('Config').first().json;
const diff = $('Get PR Diff').first().json;

// full file contents, paired by index with "List Changed Files"
const listed = $('List Changed Files').all();
const fullContent = {};
$input.all().forEach((it, i) => {
  const r = it.json || {};
  const content = r.data ?? r.body;
  if (Number(r.statusCode ?? 200) === 200 && typeof content === 'string' && listed[i]) fullContent[listed[i].json.path] = content;
});

const num = (v, d) => (Number.isFinite(Number(v)) && String(v).trim() !== '' ? Number(v) : d);
const IGNORE = String(cfg.IGNORE_PATH_REGEX || '')
  .split(',').map(s => s.trim()).filter(Boolean).map(s => new RegExp(s));
const CHUNK_MAX_FILES = num(cfg.CHUNK_MAX_FILES, 5);
const CHUNK_MAX_CHARS = num(cfg.CHUNK_MAX_CHARS, 40000);
const MAX_FILE_CHARS = num(cfg.MAX_FILE_CHARS, 60000);
const MAX_CHUNKS = num(cfg.MAX_CHUNKS, 10);
const MAX_RULES_CHARS = num(cfg.MAX_RULES_CHARS, 8000);

// ---------- repo rules (fetched by "Get Repo Rules", 404 = no rules) --------
let repoRules = '';
try {
  const r = $('Get Repo Rules').first().json;
  const status = Number(r.statusCode ?? 200);
  const content = r.data ?? r.body;   // text response -> "data"; keep "body" as fallback
  if (status === 200 && typeof content === 'string') repoRules = content.trim();
} catch (e) { /* node failed or not executed -> no repo rules */ }
const globalRules = String(cfg.GLOBAL_RULES || '').trim();
let rules = [globalRules && `General rules:\n${globalRules}`, repoRules && `Repository rules (${cfg.REPO_RULES_PATH}):\n${repoRules}`]
  .filter(Boolean).join('\n\n');
if (rules.length > MAX_RULES_CHARS) rules = rules.slice(0, MAX_RULES_CHARS) + '\n... (rules truncated)';

// ---------- parse diff into per-file blocks ---------------------------------
const pathOf = ref => (ref && (ref.toString || (ref.components || []).join('/'))) || null;
const parsed = [];
const skipped = [];

const diffs = [...(diff.diffs || [])].sort((a, b) =>
  String(pathOf(a.destination) || pathOf(a.source)).localeCompare(String(pathOf(b.destination) || pathOf(b.source))));

for (const d of diffs) {
  const newPath = pathOf(d.destination);
  const oldPath = pathOf(d.source);
  const path = newPath || oldPath;
  if (!path) continue;
  const changeType = !oldPath ? 'ADD' : !newPath ? 'DELETE' : oldPath !== newPath ? 'RENAME' : 'MODIFY';

  if (IGNORE.some(rx => rx.test(path))) { skipped.push({ path, reason: 'ignored by pattern' }); continue; }
  if (d.binary) { skipped.push({ path, reason: 'binary' }); continue; }
  if (changeType === 'DELETE') { skipped.push({ path, reason: 'deleted file' }); continue; }

  const idx = {};               // commentable lines (diff hunks only) -> anchors
  const added = new Set();
  const removedBefore = {};     // new-file line number -> removed lines shown just before it
  let body = '';
  for (const h of d.hunks || []) {
    body += `@@ -${h.sourceLine},${h.sourceSpan} +${h.destinationLine},${h.destinationSpan} @@\n`;
    let next = h.destinationLine;
    for (const seg of h.segments || []) {
      for (const l of seg.lines || []) {
        const text = l.line ?? '';
        if (seg.type === 'REMOVED') {
          (removedBefore[next] ||= []).push(text);
          body += `-       | ${text}\n`;
        } else {
          idx[String(l.destination)] = { lineType: seg.type, text };
          if (seg.type === 'ADDED') added.add(l.destination);
          next = l.destination + 1;
          body += `${seg.type === 'ADDED' ? '+' : ' '}${String(l.destination).padStart(6)} | ${text}\n`;
        }
      }
    }
  }
  if (!body) { skipped.push({ path, reason: 'no textual changes' }); continue; }

  // whole file with the changes marked in place
  let mode = 'full file';
  const content = fullContent[path];
  if (content !== undefined) {
    const lines = content.replace(/\r\n?/g, '\n').replace(/\n$/, '').split('\n');
    let full = '';
    lines.forEach((text, i) => {
      const n = i + 1;
      for (const r of removedBefore[n] || []) full += `-       | ${r}\n`;
      full += `${added.has(n) ? '+' : ' '}${String(n).padStart(6)} | ${text}\n`;
    });
    for (const r of removedBefore[lines.length + 1] || []) full += `-       | ${r}\n`;
    if (full.length <= MAX_FILE_CHARS) body = full;
    else mode = `diff only, file too large (${full.length} chars)`;
  } else {
    mode = 'diff only, full file could not be fetched';
  }
  if (mode !== 'full file' && d.truncated) body += '... (diff truncated by Bitbucket)\n';
  if (body.length > MAX_FILE_CHARS) { skipped.push({ path, reason: `diff too large (${body.length} chars)` }); continue; }

  parsed.push({ path, srcPath: changeType === 'RENAME' ? oldPath : null, changeType, oldPath, body, idx, mode });
}

// ---------- global file ids, then chunk (files sorted by path keep modules together)
parsed.forEach((p, i) => { p.fid = `F${i + 1}`; });

const chunks = [];
let cur = null;
for (const p of parsed) {
  const header = `\n### ${p.fid}  ${p.path}  (${p.changeType}${p.changeType === 'RENAME' ? ` from ${p.oldPath}` : ''}, ${p.mode})\n`;
  const block = header + p.body;
  if (!cur || cur.files.length >= CHUNK_MAX_FILES || (cur.chars + block.length > CHUNK_MAX_CHARS && cur.files.length > 0)) {
    cur = { files: [], chars: 0, text: '', lineIndex: {} };
    chunks.push(cur);
  }
  cur.files.push({ fid: p.fid, path: p.path, srcPath: p.srcPath, changeType: p.changeType });
  cur.lineIndex[p.path] = p.idx;
  cur.text += block;
  cur.chars += block.length;
}

if (chunks.length > MAX_CHUNKS) {
  for (const c of chunks.splice(MAX_CHUNKS)) for (const f of c.files) skipped.push({ path: f.path, reason: 'PR too large (MAX_CHUNKS reached)' });
}

if (!chunks.length) return [{ json: { hasFiles: false, hasRules: false, skipped } }];

const allPaths = chunks.flatMap(c => c.files.map(f => `${f.fid} = ${f.path}`));
const skippedList = skipped.map(s => `- ${s.path} (${s.reason})`).join('\n') || '(none)';

return chunks.map((c, i) => ({
  json: {
    hasFiles: true,
    hasRules: rules.length > 0,
    chunkIndex: i + 1,
    chunkCount: chunks.length,
    files: c.files,
    lineIndex: c.lineIndex,
    skipped,
    annotatedDiff: c.text,
    fileList: c.files.map(f => `${f.fid} = ${f.path}`).join('\n'),
    otherFiles: allPaths.filter(p => !c.files.some(f => p.startsWith(f.fid + ' '))).join('\n') || '(none)',
    skippedList,
    repoRules: rules,
  },
}));

