// ============================================================================
// n8n Code node: "Resolve Anchors"   (Mode: Run Once for All Items)
//
// Collects the results of BOTH reviewers and outputs ONE item with all candidates.
//   AI Code Reviewer  -> source 'general'
//   AI Rules Reviewer -> source 'rules'   (only when repo rules exist)
// The LLM's location is treated as a HINT only:
//   * path -> always taken from the parsed diff (file_id lookup, or the LLM's
//             path matched against real diff paths). Never the raw LLM string.
//   * line -> must exist in the diff line index. If the LLM's line is wrong,
//             code_snippet is searched in the real diff lines; nearest match wins.
// Unpinnable issues: UNANCHORED_MODE = 'drop' | 'file' (file-level, real path).
//
// IMPORTANT: only literal $('Node Name') calls in this node. A dynamic $(name)
// makes the task runner ship the ENTIRE execution data (all LLM sub-node runs)
// and the node hangs.
// ============================================================================

const cfg = $('Config').first().json;
const chunkItems = $('Build Review Context').all().map(i => i.json);
const rulesText = chunkItems[0]?.repoRules || '';

const num = (v, d) => (Number.isFinite(Number(v)) && String(v).trim() !== '' ? Number(v) : d);
const UNANCHORED_MODE = cfg.UNANCHORED_MODE || 'drop';
const NEAR_WINDOW = num(cfg.LINE_TOLERANCE, 3);
const MIN_CONFIDENCE = num(cfg.MIN_CONFIDENCE, 0.5);
const CONTEXT_RADIUS = 8;

// ---------- merge per-chunk context ----------------------------------------
const files = chunkItems.flatMap(c => c.files || []);
const lineIndex = Object.assign({}, ...chunkItems.map(c => c.lineIndex || {}));
const byFid = Object.fromEntries(files.map(f => [f.fid.toUpperCase(), f]));
const byPath = Object.fromEntries(files.map(f => [f.path, f]));

// ---------- parse agent output robustly ------------------------------------
function extractIssues(out) {
  if (Array.isArray(out)) return out;
  if (out && typeof out === 'object') {
    if (Array.isArray(out.issues)) return out.issues;
    if (out.output !== undefined) return extractIssues(out.output);
    return null;
  }
  if (typeof out !== 'string') return null;
  let s = out.replace(/<think>[\s\S]*?<\/think>/gi, '').replace(/```(?:json)?/gi, '').trim();
  for (const [open, close] of [['{', '}'], ['[', ']']]) {
    const a = s.indexOf(open), b = s.lastIndexOf(close);
    if (a !== -1 && b > a) {
      try { const r = extractIssues(JSON.parse(s.slice(a, b + 1))); if (r) return r; } catch (e) { /* next */ }
    }
  }
  return null;   // null = unparseable (different from "no issues")
}

// ---------- collect reviewer outputs (literal node names only) -------------
// .all() throws when the node did not run; empty also means "did not run"
// (an agent emits one item per input chunk, errors included).
const safeAll = fn => { try { const a = fn(); return a && a.length ? a.map(i => i.json) : null; } catch (e) { return null; } };
const REVIEWERS = [
  { source: 'general', items: safeAll(() => $('AI Code Reviewer').all()) },
  { source: 'rules',   items: safeAll(() => $('AI Rules Reviewer').all()) },
];

const report = { chunks: chunkItems.length, rulesReview: rulesText ? 'not run' : 'skipped (no rules)',
                 failedChunks: [], received: { general: 0, rules: 0 }, lowConfidence: 0,
                 anchored: 0, relocated: 0, fileLevel: 0, duplicates: 0, dropped: [] };
const issues = [];

for (const r of REVIEWERS) {
  const agentItems = r.items;
  if (!agentItems) continue;
  if (r.source === 'rules') report.rulesReview = 'ran';
  agentItems.forEach((a, i) => {
    const chunkNo = chunkItems[i]?.chunkIndex ?? i + 1;
    const chunkFiles = (chunkItems[i]?.files || []).map(f => f.path);
    if (a.error) {
      report.failedChunks.push({ source: r.source, chunk: chunkNo, files: chunkFiles, error: String(a.error.message || a.error).slice(0, 300) });
      return;
    }
    const parsed = extractIssues(a.output ?? a.text ?? a);
    if (parsed === null) {
      report.failedChunks.push({ source: r.source, chunk: chunkNo, files: chunkFiles, error: 'reviewer output was not valid JSON' });
      return;
    }
    parsed.forEach(x => issues.push({ ...x, _chunk: chunkNo, _source: r.source }));
    report.received[r.source] += parsed.length;
  });
}

// ---------- location resolution --------------------------------------------
const norm = s => String(s ?? '').replace(/\s+/g, ' ').trim();

function resolveFile(issue) {
  const fid = String(issue.file_id ?? '').trim().toUpperCase();
  if (byFid[fid]) return { file: byFid[fid], how: 'file_id' };
  const p = String(issue.path ?? issue.file ?? '').trim().replace(/^\/+/, '').replace(/^[ab]\//, '');
  if (!p) return null;
  if (byPath[p]) return { file: byPath[p], how: 'exact_path' };
  const cands = files.filter(f => f.path.endsWith('/' + p) || p.endsWith('/' + f.path));
  return cands.length === 1 ? { file: cands[0], how: 'suffix_path' } : null;
}

function resolveLine(path, claimed, snippet) {
  const idx = lineIndex[path] || {};
  const claimedNum = Number.parseInt(claimed, 10);
  const snip = norm(snippet);
  const entry = idx[String(claimedNum)];
  const t = entry ? norm(entry.text) : '';

  if (entry && (!snip || t.includes(snip) || (t.length > 3 && snip.includes(t)))) {
    return { line: claimedNum, lineType: entry.lineType, how: 'exact' };
  }
  if (snip.length >= 4) {
    const hits = Object.entries(idx)
      .filter(([, v]) => norm(v.text).includes(snip) || (norm(v.text).length > 8 && snip.includes(norm(v.text))))
      .map(([n, v]) => ({ n: Number(n), v }))
      .sort((x, y) =>
        (x.v.lineType === 'ADDED' ? 0 : 1) - (y.v.lineType === 'ADDED' ? 0 : 1) ||
        Math.abs(x.n - (claimedNum || 0)) - Math.abs(y.n - (claimedNum || 0)));
    if (hits.length) return { line: hits[0].n, lineType: hits[0].v.lineType, how: 'snippet_relocated' };
  }
  if (!snip && Number.isFinite(claimedNum)) {
    for (let d = 1; d <= NEAR_WINDOW; d++) {
      for (const n of [claimedNum - d, claimedNum + d]) {
        if (idx[String(n)]?.lineType === 'ADDED') return { line: n, lineType: 'ADDED', how: `nearest_added(${d})` };
      }
    }
  }
  return null;
}

function codeContext(path, line) {
  const idx = lineIndex[path] || {};
  if (!line) return '(file-level issue, no inline context)';
  const out = [];
  for (let n = line - CONTEXT_RADIUS; n <= line + CONTEXT_RADIUS; n++) {
    const e = idx[String(n)];
    if (e) out.push(`${n === line ? '>>' : '  '}${e.lineType === 'ADDED' ? '+' : ' '}${String(n).padStart(6)} | ${e.text}`);
  }
  return out.join('\n');
}

// ---------- build candidates -----------------------------------------------
const seen = new Set();
const candidates = [];

for (const issue of issues) {
  const source = issue._source;
  const conf = Number(issue.confidence);
  if (Number.isFinite(conf) && conf < MIN_CONFIDENCE) { report.lowConfidence++; continue; }

  let f = resolveFile(issue);
  let loc = f ? resolveLine(f.file.path, issue.line, issue.code_snippet) : null;

  // wrong / unknown file id: accept another file only if the snippet matches lines in exactly ONE file of the PR
  if (!loc && norm(issue.code_snippet).length >= 10) {
    const owners = files.filter(x => (!f || x.path !== f.file.path) && resolveLine(x.path, null, issue.code_snippet));
    if (owners.length === 1) {
      f = { file: owners[0], how: 'snippet_file_match' };
      loc = resolveLine(f.file.path, issue.line, issue.code_snippet);
    }
  }

  if (!f) { report.dropped.push({ source, reason: 'unknown file', path: issue.path, file_id: issue.file_id, title: issue.title }); continue; }
  const path = f.file.path;   // <- from the diff, never from the LLM

  if (!loc && UNANCHORED_MODE !== 'file') {
    report.dropped.push({ source, reason: 'line not in diff', path, line: issue.line, title: issue.title });
    continue;
  }
  const line = loc ? loc.line : null;
  const key = `${source}:${path}:${line ?? 'file'}:${norm(issue.title).toLowerCase()}`;
  if (seen.has(key)) { report.duplicates++; continue; }
  seen.add(key);

  if (!loc) report.fileLevel++;
  else if (loc.how === 'exact') report.anchored++;
  else report.relocated++;

  candidates.push({
    id: `C${candidates.length + 1}`,
    source,
    rule: source === 'rules' ? norm(issue.rule).slice(0, 400) : null,
    path, srcPath: f.file.srcPath, line, lineType: loc?.lineType ?? null,
    resolution: `${f.how}/${loc ? loc.how : 'file_level'}`,
    claimedLine: issue.line ?? null,
    severity: String(issue.severity || 'medium').toLowerCase(),
    category: issue.category || (source === 'rules' ? 'repo-rule' : null),
    confidence: Number.isFinite(conf) ? conf : null,
    title: norm(issue.title) || 'Issue',
    description: String(issue.description || '').trim(),
    suggestion: String(issue.suggestion || '').trim(),
    context: codeContext(path, line),
  });
}

// ---------- prompt for the verification pass -------------------------------
const hasRuleCandidates = candidates.some(c => c.source === 'rules');
const verifyPrompt =
  (hasRuleCandidates ? `REVIEW RULES (judge RULE VIOLATION candidates only against these):\n${rulesText}\n\n` : '') +
  'Candidate issues:\n\n' +
  candidates.map(c =>
    `=== ${c.id} | ${c.source === 'rules' ? 'RULE VIOLATION' : 'CODE ISSUE'} | ${c.severity.toUpperCase()} | ${c.path}${c.line ? `:${c.line}` : ''}\n` +
    (c.rule ? `Rule: ${c.rule}\n` : '') +
    `Title: ${c.title}\nClaim: ${c.description}\n` +
    (c.suggestion ? `Suggested fix: ${c.suggestion}\n` : '') +
    `Code (>> marks the commented line, + = added in this PR):\n${c.context}\n`).join('\n');

return [{ json: { hasCandidates: candidates.length > 0, candidates, verifyPrompt, report } }];

// ============================================================================
// n8n Code node: "Apply Verdicts"   (Mode: Run Once for All Items)
//
// Filters candidates with the verifier's verdicts, caps, and emits:
//   kind = 'comment' -> inline comment / task  (Post Inline Comment / Task)
//   kind = 'notice'  -> one general PR comment when part of the review failed
// ============================================================================

const cfg = $('Config').first().json;
const { candidates = [], report = {} } = $('Resolve Anchors').first().json;

const num = (v, d) => (Number.isFinite(Number(v)) && String(v).trim() !== '' ? Number(v) : d);
const MAX_COMMENTS = num(cfg.MAX_COMMENTS, 25);
const TASK_SEVERITIES = String(cfg.TASK_SEVERITIES || 'critical,high').split(',').map(s => s.trim().toLowerCase());
const VERIFY_FAIL_MODE = String(cfg.VERIFY_FAIL_MODE || 'keep_high');   // keep_all | keep_high | drop_all
const POST_FAILURE_NOTICE = String(cfg.POST_FAILURE_NOTICE ?? 'true') === 'true';
const SEV_RANK = { critical: 0, high: 1, medium: 2, low: 3 };
const SEV_ICON = { critical: '🔴', high: '🟠', medium: '🟡', low: '🔵' };
const SOURCE_LABEL = { general: 'code review', rules: 'repo rules review' };

// ---------- read verifier output (if it ran) --------------------------------
let verdicts = null;      // Map id -> {keep, reason, severity}
let verifyError = null;
let verifyRan = false;
try { verifyRan = $('Verify Issues').isExecuted; } catch (e) { verifyRan = false; }

if (verifyRan && candidates.length) {
  const v = $input.first().json;
  if (v.error) {
    verifyError = String(v.error.message || v.error).slice(0, 300);
  } else {
    const raw = String(v.text ?? v.output ?? '').replace(/<think>[\s\S]*?<\/think>/gi, '').replace(/```(?:json)?/gi, '');
    const a = raw.indexOf('{'), b = raw.lastIndexOf('}');
    try {
      const parsed = JSON.parse(raw.slice(a, b + 1));
      verdicts = new Map((parsed.verdicts || []).map(x => [String(x.id).toUpperCase(), x]));
    } catch (e) {
      verifyError = 'verifier output was not valid JSON';
    }
  }
}

// ---------- filter ----------------------------------------------------------
report.verification = verdicts ? 'ok' : verifyError ? `failed: ${verifyError} (mode ${VERIFY_FAIL_MODE})` : 'skipped';
report.rejectedByVerifier = [];

const kept = [];
for (const c of candidates) {
  if (verdicts) {
    const v = verdicts.get(c.id.toUpperCase());
    if (v && v.keep === false) { report.rejectedByVerifier.push({ id: c.id, source: c.source, title: c.title, reason: v.reason }); continue; }
    if (v && SEV_RANK[String(v.severity).toLowerCase()] !== undefined) c.severity = String(v.severity).toLowerCase();
  } else if (verifyError) {
    if (VERIFY_FAIL_MODE === 'drop_all') continue;
    if (VERIFY_FAIL_MODE === 'keep_high' && SEV_RANK[c.severity] > 1) continue;
  }
  kept.push(c);
}

kept.sort((a, b) => (SEV_RANK[a.severity] ?? 9) - (SEV_RANK[b.severity] ?? 9));
const posted = kept.slice(0, MAX_COMMENTS);
report.cappedOut = Math.max(0, kept.length - MAX_COMMENTS);
report.posting = posted.length;

// ---------- build Bitbucket payloads ----------------------------------------
function text(c) {
  const isRule = c.source === 'rules';
  const head = `${SEV_ICON[c.severity] || '⚪'} **[${c.severity.toUpperCase()}] ${isRule ? 'Rule violation: ' : ''}${c.title}**${c.category ? `  \`${c.category}\`` : ''}`;
  const parts = [head];
  if (isRule && c.rule) parts.push(`> **Rule:** ${c.rule}`);
  if (c.description) parts.push(c.description);
  if (c.suggestion) parts.push(`**Suggestion:**\n${c.suggestion}`);
  if (!c.line && c.claimedLine) parts.push(`_Reported near line ${c.claimedLine} (outside the PR diff, could not be pinned inline)._`);
  parts.push(isRule ? '_— AI review (repo rules)_' : '_— AI review_');
  return parts.join('\n\n');
}

const out = posted.map(c => ({
  json: {
    kind: 'comment',
    source: c.source,
    path: c.path, line: c.line, resolution: c.resolution,
    body: {
      text: text(c),
      severity: TASK_SEVERITIES.includes(c.severity) ? 'BLOCKER' : 'NORMAL',   // BLOCKER = Bitbucket task
      anchor: {
        diffType: 'EFFECTIVE',
        path: c.path,
        ...(c.srcPath ? { srcPath: c.srcPath } : {}),
        ...(c.line ? { line: c.line, lineType: c.lineType } : {}),
        fileType: 'TO',
      },
    },
    report,
  },
}));

// ---------- failure notice ---------------------------------------------------
const failed = report.failedChunks || [];
if (POST_FAILURE_NOTICE && (failed.length || verifyError)) {
  const lines = ['⚠️ **AI review was incomplete**'];
  if (failed.length) {
    lines.push(`${failed.length} review part(s) failed, so these files may be missing AI comments:`);
    for (const f of failed) lines.push(`- [${SOURCE_LABEL[f.source] || f.source}] ${f.files.map(p => `\`${p}\``).join(', ')}  _(${f.error})_`);
  }
  if (verifyError) {
    const what = { keep_all: 'all issues were posted unverified',
                   keep_high: 'only critical/high issues were posted, unverified',
                   drop_all: 'no issues were posted' }[VERIFY_FAIL_MODE] || VERIFY_FAIL_MODE;
    lines.push(`The false-positive check failed (${verifyError}); ${what}.`);
  }
  lines.push('_— AI review_');
  out.push({ json: { kind: 'notice', body: { text: lines[0] + '\n\n' + lines.slice(1).join('\n') }, report } });
}

return out;   // empty -> nothing to post, workflow ends here

