const e = $input.first().json.error || $input.first().json;
const msg = String(e.message || e.description || JSON.stringify(e)).slice(0, 300);
return [{
  json: {
    kind: 'notice',
    body: { text: `⚠️ **AI review could not run**\n\nFetching the PR diff failed: \`${msg}\`\n\n_— AI review_` },
  },
}];

