// n8n Code node: "List Changed Files"   (Mode: Run Once for All Items)
//
// One item per changed file worth reviewing, so "Get Changed File" can fetch
// its full content at the PR source commit. Same filters as "Build Review Context".
// ============================================================================
const cfg = $('Config').first().json;
const IGNORE = String(cfg.IGNORE_PATH_REGEX || '')
  .split(',').map(s => s.trim()).filter(Boolean).map(s => new RegExp(s));
const pathOf = ref => (ref && (ref.toString || (ref.components || []).join('/'))) || null;

return ($input.first().json.diffs || [])
  .map(d => ({ path: pathOf(d.destination), binary: d.binary }))
  .filter(f => f.path && !f.binary && !IGNORE.some(rx => rx.test(f.path)))
  .map(f => ({ json: { path: f.path } }));
